import math
from pathlib import Path
from devtools.resources.filesystem import JsonCodec, FileFormatError
from devtools.core.paths import resolve_path
c=JsonCodec(); p=resolve_path(Path.cwd()/'number.json')
for text in ['1e999','-1e999','[0,1e999]','{"x":[{"n":-1e999}]}']:
    for call in (lambda: c.parse(p,text),lambda:c.decode(p,text.encode())):
        try: call()
        except FileFormatError as e: assert e.__cause__ is not None and str(e)
        else: raise AssertionError('Nonfinite parsed number accepted: '+text)
for text in ['1e308','-1e308','1e-999','1234567890123456789012345678901234567890','{"s":"1e999","n":1.5}']:
    f=c.parse(p,text); assert f.content==text and f.byte_size==len(text.encode())
    assert c.parse(p,c.serialize(f)).value==f.value
assert c.parse(p,'1234567890123456789012345678901234567890').value==1234567890123456789012345678901234567890
